const tools = {
  name: "tools",
  wrap(fn) {
    return (...args) => fn.apply(this, args);
  },
  wrapWell(fn) {
    return function (...args) {
      return fn.apply(this, args);
    };
  },
};

const cat = {
  name: "cat",
  describe(mood) {
    return `${this.name} is ${mood}`;
  },
};

cat.nap = tools.wrap(cat.describe);
cat.play = tools.wrapWell(cat.describe);

console.log(cat.nap("sleepy"));
console.log(cat.play("busy"));
console.log(cat.play.call(tools, "open"));
